getFloor() {
  this.form.floorNumber = add(this.form.floorNumberAbove, this.form.floorNumberUnder)
},
/** 选择证书前需先有所属项目 */
checkProjectBeforeCertSelect() {
  if (!this.form.projectId) {
    this.msgWarning('请先选择所属项目')
    return false
  }
  return true
},
/** 选择建设工程规划许可证（与楼幢维护一致：只取该项目下已备案的证书） */
openPlanLicSelect() {
  if (this.isFormDisabled) return
  if (!this.checkProjectBeforeCertSelect()) return
  SelectDialog.open({
    title: '选择建设工程规划许可证',
    url: '/presale/planLic/page',
    rowKey: 'conEngPlanLicId',
    filterParams: { projectId: this.form.projectId, bizState: '2' },
    columns: [
      { type: 'index', label: '序号', prop: 'index' },
      { label: '规划许可证号', prop: 'conEngPlanLicCode' },
      { label: '建设单位', prop: 'construtUnit' },
      { label: '发证日期', prop: 'licenceDate' }
    ]
  })
    .then((row) => {
      this.form.constructionPlanningPermitCode = row.conEngPlanLicCode
    })
    .catch(() => {})
},
clearPlanLicSelect() {
  this.form.constructionPlanningPermitCode = undefined
},
/** 选择建设工程施工许可证 */
openConsLicSelect() {
  if (this.isFormDisabled) return
  if (!this.checkProjectBeforeCertSelect()) return
  SelectDialog.open({
    title: '选择建设工程施工许可证',
    url: '/presale/consLic/page',
    rowKey: 'conEngConsLicId',
    filterParams: { projectId: this.form.projectId, bizState: '2' },
    columns: [
      { type: 'index', label: '序号', prop: 'index' },
      { label: '施工许可证号', prop: 'conEngConsLicCode' },
      { label: '建设单位', prop: 'buildUnit' },
      { label: '工程名称', prop: 'engName' },
      { label: '施工合同号', prop: 'constructContractNo' },
      { label: '发证日期', prop: 'licenceDate' }
    ]
  })
    .then((row) => {
      this.form.constructionPermitCode = row.conEngConsLicCode
    })
    .catch(() => {})
},
clearConsLicSelect() {
  this.form.constructionPermitCode = undefined
},

